def run_all(tasks):
    errors = []
    for fn in tasks:
        try:
            fn()
        except Exception as exc:
            errors.append(exc)
    if errors:
        raise ExceptionGroup("batch failed", errors)

def bad_value():
    raise ValueError("bad value")

def bad_type():
    raise TypeError("bad type")

try:
    run_all([bad_value, bad_type, bad_value])
except* ValueError as eg:
    print("ValueError x", len(eg.exceptions))
except* TypeError as eg:
    print("TypeError x", len(eg.exceptions))
